type DoltDatabaseProvider struct {
	fs           filesys.Filesys
	remoteDialer dbfactory.GRPCDialProvider // TODO: why isn't this a method defined on the remote object

	// dbLoadParams are optional parameters to apply when loading local file-backed databases created
	// via provider-managed code paths (e.g. CREATE DATABASE / dolt_clone / undrop). These should match
	// the params threaded into env.DoltEnv.DBLoadParams by higher layers (e.g. engine.SqlEngineConfig.DBLoadParams).
	//
	// Note: these params are only effective if they are set before the underlying DoltDB is loaded.
	dbLoadParams map[string]interface{}

	// dbLocations maps a database name to its file system root
	dbLocations            map[string]filesys.Filesys
	databases              map[string]dsess.SqlDatabase
	functions              map[string]sql.Function
	tableFunctions         map[string]sql.TableFunction
	externalProcedures     sql.ExternalStoredProcedureRegistry
	isStandby              *bool
	mu                     *sync.RWMutex
	droppedDatabaseManager *droppedDatabaseManager
	overrides              sql.EngineOverrides

	// Databases named in deletingDatbases are currently undergoing deletion.
	// Databases with these names cannot created, but also return ErrNoDatabase
	// when accessed.
	deletingDatabases map[string]struct{}

	// creatingDatabases reserves names for clones fetching data from a remote.
	// CloneDatabaseFromRemote drops the provider lock for that network fetch, so
	// it records the name here to keep concurrent CREATE DATABASE / dolt_clone /
	// undrop of the same name serialized. Names are normalized with
	// formatDbMapKeyName, like p.databases (Dolt names are case-insensitive).
	//
	// Unlike deletingDatabases, this does not gate enumeration: enumeration only
	// ever reads the in-memory p.databases map at runtime, so an in-progress
	// clone's on-disk directory is simply invisible until it registers.
	creatingDatabases map[string]struct{}

	txLocks keymutex.Keymutex

	defaultBranch     string
	dbFactoryUrl      string
	DropDatabaseHooks []DropDatabaseHook
	InitDatabaseHooks []InitDatabaseHook
	gitRemotes        map[string]*doltdb.DoltDB
	gitRemotesMu      *sync.Mutex
}

// ProviderFactory creates a sql.DatabaseProvider for use as the engine's analyzer catalog
// provider.

	// TODO: kill this
	SetCWBHeadRef(context.Context, ref.MarshalableRef) error
	AddRemote(r Remote) error
	AddBackup(r Remote) error
	RemoveRemote(ctx context.Context, name string) error
	RemoveBackup(ctx context.Context, name string) error
	TempTableFilesDir() (string, error)
	UpdateBranch(name string, new BranchConfig) error
}

type RepoStateReadWriter[C doltdb.Context] interface {
	RepoStateReader[C]
	RepoStateWriter
}

// RemoteDbProvider is an interface for getting a database from a remote
type RemoteDbProvider interface {
	GetRemoteDB(ctx context.Context, format *types.NomsBinFormat, r Remote) (*doltdb.DoltDB, error)
}
type DbData[C doltdb.Context] struct {
	Ddb *doltdb.DoltDB
	Rsw RepoStateWriter
	Rsr RepoStateReader[C]
}

type BranchConfig struct {
	Merge  ref.MarshalableRef `json:"head"`
	Remote string             `json:"remote"`
}

type RepoState struct {
	Head     ref.MarshalableRef                       `json:"head"`
	Remotes  *concurrentmap.Map[string, Remote]       `json:"remotes"`
	Backups  *concurrentmap.Map[string, Remote]       `json:"backups"`
	Branches *concurrentmap.Map[string, BranchConfig] `json:"branches"`
	// |staged|, |working|, and |merge| are legacy fields left over from when Dolt repos stored this info in the repo
	// state file, not in the DB directly. They're still here so that we can migrate existing repositories forward to the
	// new storage format, but they should be used only for this purpose and are no longer written.
	staged  string
	working string

// establish the in memory state of the session for every new transaction.
type InitialDbState struct {
	DbData env.DbData[*sql.Context]
	Db     sql.Database
	// HeadRoot is the root value for databases without a HeadCommit. Nil for databases with a HeadCommit.
	HeadRoot doltdb.RootValue
	// If err is set, this InitialDbState is partially invalid, but may be
	// usable to initialize a database at a revision specifier, for
	// example. Adding this InitialDbState to a session will return this
	// error.
	Err error
	// WorkingSet is the working set for this database. May be nil for databases tied to a detached root value, in which
	// case HeadCommit must be set
	WorkingSet *doltdb.WorkingSet
	// The head commit for this database. May be nil for databases tied to a detached root value, in which case
	// RootValue must be set.
	HeadCommit *doltdb.Commit
	Remotes    *concurrentmap.Map[string, env.Remote]
	Branches   *concurrentmap.Map[string, env.BranchConfig]
	Backups    *concurrentmap.Map[string, env.Remote]
	ReadOnly   bool
}

// SessionDatabase is a database that can be managed by a dsess.Session. It has methods to return its initial state in
// order for the session to manage it.
type SessionDatabase interface {
	sql.Database
	InitialDBState(ctx *sql.Context) (InitialDbState, error)
}

// DatabaseSessionState is the set of all information for a given database in this session.
type DatabaseSessionState struct {
	// globalState is the global state of this session (shared by all sessions for a particular db)
	globalState globalstate.GlobalState
	// Same as InitialDbState.Err, this signifies that this
	// DatabaseSessionState is invalid. LookupDbState returning a
	// DatabaseSessionState with Err != nil will return that err.
	Err error
	// heads records the in-memory DB state for every branch head accessed by the session
	heads map[string]*branchState
	// headCache records the session-caches for every branch head accessed by the session
	// This is managed separately from the branch states themselves because it persists across transactions (which is
	// safe because it's keyed by immutable hashes)
	headCache map[string]*SessionCache
	// dbName is the name of the database this state applies to. This is always the base name of the database, without
	// a revision qualifier.
	dbName string
	// checkedOutRevSpec is the revision of the database when referred to by its base name. Changes only when a
	// `dolt_checkout` occurs.
	checkedOutRevSpec string
	// tmpFileDir is the directory to use for temporary files for this database
	tmpFileDir string
}

func newEmptyDatabaseSessionState() *DatabaseSessionState {
	return &DatabaseSessionState{
		heads:     make(map[string]*branchState),
		headCache: make(map[string]*SessionCache),
